2	//!
3	//! Two primitives operate on BYTE LISTS — `(List Int)` with every element in
4	//! `0..255` — rather than on scalars:
5	//!
6	//!   * `hmac-sha256 key msg : (List Int)` — RFC 2104 keyed hashing with
7	//!     SHA-256, returning the 32-byte digest.
8	//!   * `bytes-eq-ct a b : Bool` — equality that examines EVERY byte, so it
9	//!     does not leak the position of the first difference through timing.
10	//!
11	//! Both are deliberately OUTSIDE the provable fragment (SPEC §7): a property
12	//! whose goal reaches either is recorded `tested`, never `proven`. That is
13	//! enforced in `prove.rs`, not here.
14	//!
15	//! Implemented by hand on top of the SHA-256 already used for object identity,
16	//! so no HMAC crate is pulled in and the wasm build keeps its dependency
17	//! surface (pure computation only — see lib.rs).
18	
19	use crate::hash::sha256;
20	
21	/// SHA-256's block size in bytes (RFC 2104's `B`).
22	const BLOCK: usize = 64;
23	
24	/// HMAC-SHA256 (RFC 2104 with SHA-256): `H((K ⊕ opad) ‖ H((K ⊕ ipad) ‖ msg))`,
25	/// where `K` is `key` hashed down if longer than one block and zero-padded up
26	/// to one block otherwise. Returns the 32-byte digest.
27	pub fn hmac_sha256(key: &[u8], msg: &[u8]) -> Vec<u8> {
28	    // RFC 2104 §2: keys longer than the block size are replaced by their own
29	    // digest; shorter keys are right-padded with zeros to the block size.
30	    let mut k = [0u8; BLOCK];
31	    if key.len() > BLOCK {
32	        k[..32].copy_from_slice(&sha256(key));
33	    } else {
34	        k[..key.len()].copy_from_slice(key);
35	    }
36	
37	    let mut inner = Vec::with_capacity(BLOCK + msg.len());
38	    for b in k.iter() {
39	        inner.push(b ^ 0x36); // ipad
40	    }
41	    inner.extend_from_slice(msg);
42	    let inner_digest = sha256(&inner);
43	
44	    let mut outer = Vec::with_capacity(BLOCK + 32);
45	    for b in k.iter() {
46	        outer.push(b ^ 0x5c); // opad
47	    }
48	    outer.extend_from_slice(&inner_digest);
49	    sha256(&outer).to_vec()
50	}
51	
52	/// Constant-time byte-list equality (SPEC §1.3). Every byte of the longer
53	/// operand is examined regardless of where the two first differ — there is no
54	/// early exit — so the running time is a function of the LENGTHS only, which
55	/// are not the secret. Differing lengths compare unequal; the missing tail is
56	/// folded in as zero bytes purely to keep the loop shape uniform, and the
57	/// length mismatch is what decides the result.
58	pub fn bytes_eq_ct(a: &[u8], b: &[u8]) -> bool {
59	    let n = if a.len() > b.len() { a.len() } else { b.len() };
60	    let mut diff: u8 = 0;
61	    for i in 0..n {
62	        let x = if i < a.len() { a[i] } else { 0 };
63	        let y = if i < b.len() { b[i] } else { 0 };
64	        diff |= x ^ y;
65	    }
66	    // `&`, not `&&`: no short-circuit, so neither operand's evaluation is
67	    // skipped on the basis of the other.
68	    (diff == 0) & (a.len() == b.len())
69	}
