569	/// Build the SPEC §1.5 golden O1 encoding Defs by hand and compare against the
570	/// fixture .bin files (byte-identity + manifest hash), then round-trip each
571	/// through the strict decoder.
572	fn cmd_enctest(dir: &str) -> i32 {
573	    // a fixed 32-byte hash reference: 00 11 22 .. ff repeated twice
574	    let href = "00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff".to_string();
575	    let cases: Vec<(&str, Def)> = vec![
576	        ("bool_bytes", Def::Func { tyvars: 0, ty: Ty::Bool, body: Term::Bool(false), props: vec![] }),
577	        (
578	            "empty_lists",
579	            Def::Func {
580	                tyvars: 0,
581	                ty: Ty::Int,
582	                body: Term::Int(num_bigint::BigInt::from(0)),
583	                props: vec![Prop { binders: vec![], body: Term::Bool(true) }],
584	            },
585	        ),
586	        (
587	            "hash_reference",
588	            Def::Func {
589	                tyvars: 0,
590	                ty: Ty::Bool,
591	                body: Term::Ctor { hash: href, idx: 0, tyargs: vec![], args: vec![Term::Bool(false)] },
592	                props: vec![],
