            while i < args.len() {
                match args[i].as_str() {
                    "--outcomes" => {
                        outcomes = args.get(i + 1).cloned();
                        i += 2;
                    }
                    _ => {
                        files.push(args[i].clone());
                        i += 1;
                    }
                }
