1	//! Campaign identity (SPEC §11).
2	//!
3	//! A mutation score is only trustworthy if the computation that produced it has
4	//! a reproducible identity, so the score is attached to the digest of a
5	//! CAMPAIGN DESCRIPTION and a consumer decides freshness by comparing digests
6	//! (§11.3: MEASURED / STALE / UNMEASURED).
7	//!
8	//! This module implements ONLY the identity — the pure pair
9	//!
10	//! ```text
11	//! campaignEncode : CampaignDescription -> bytes
12	//! campaignHash   : CampaignDescription -> Hash
13	//! ```
14	//!
15	//! It does not implement a mutation engine, a worker, scheduling or storage:
16	//! §11 says those are registry concerns and are deliberately unspecified. Like
17	//! the rest of the library this is pure computation (no fs, no process), so it
18	//! cross-compiles to wasm unchanged.
19	//!
20	//! The split between the two functions is load-bearing. §11.2 states the
21	//! encoding is CANONICAL BY DEFINITION — it emits exactly one byte
22	//! representation for every semantically identical description — so ALL
23	//! normalization lives in `campaign_encode`, and `campaign_hash` is a thin
24	//! wrapper that hashes the bytes and interprets nothing. If the hash had to
25	//! re-normalize, an auditor who hashed the encoded bytes directly would get a
26	//! different answer while believing they had followed §11.
27	
28	use crate::hash::{sha256_hex, sha256};
29	
30	/// The domain separator line (§11.2). It is a LINE: LF-terminated like every
31	/// other, and it sits FIRST, before any field.
32	pub const CAMPAIGN_DOMAIN: &str = "oath-campaign/1";
33	
34	/// A campaign description (§11.1). Every field is identity-bearing: each one
35	/// can change the outcome the score reports.
36	///
37	/// Field ORDER in this struct is the encoding order fixed by §11.2 and is not
38	/// free to change — reordering forks every campaign identity.
39	#[derive(Clone, Debug, PartialEq, Eq)]
40	pub struct CampaignDescription {
41	    /// Content hash of the ONE object the score is about — 64 lowercase hex.
42	    pub artifact: String,
43	    /// Kernel version string: evaluation semantics decide whether a mutant is
44	    /// caught.
45	    pub kernel: String,
46	    /// Mutant-generator revision. A new mutation kind is a different campaign.
47	    pub engine: String,
48	    /// Generated cases per mutant. A survivor at 60 may be a kill at 600, so
49	    /// the budget is part of the claim.
50	    pub cases: u64,
51	    /// Evaluation budget per case.
52	    pub fuel: u64,
53	    /// How waivers affect the score.
54	    pub waiver_policy: String,
55	    /// The waived-mutant SET, keyed by mutant hash (64 lowercase hex each).
56	    ///
57	    /// §11.2: order and multiplicity are BOTH non-semantic here, and this is
58	    /// the ONLY set-valued field in the description. It is stored as a `Vec`
59	    /// because a description is whatever an auditor reconstructs — possibly
60	    /// unsorted, possibly repeating — and the encoder is what makes it
61	    /// canonical. Do not generalize this treatment: an ordered execution
62	    /// phase or a staged mutation sequence would be a SEQUENCE, and sorting or
63	    /// deduplicating it would erase meaning rather than canonicalize it.
64	    pub waivers: Vec<String>,
65	}
66	
67	/// `campaignEncode` (§11.2) — the canonical byte encoding.
68	///
69	/// Domain separator line, then one `key=value` line per field in exactly the
70	/// §11.2 order, each terminated by a single LF (0x0A). No spaces around `=`, no
71	/// trailing blank line, UTF-8 throughout.
72	///
73	/// This function is TOTAL, matching the signature §11 states
74	/// (`CampaignDescription -> bytes`): §11 gives `campaignEncode` no error path.
75	/// Shape checking is available separately as [`CampaignDescription::validate`]
76	/// and is deliberately not on the encoding path.
77	pub fn campaign_encode(d: &CampaignDescription) -> Vec<u8> {
78	    let mut out = String::new();
79	
80	    out.push_str(CAMPAIGN_DOMAIN);
81	    out.push('\n');
82	
83	    // The field order below is normative (§11.2).
84	    push_field(&mut out, "artifact", &d.artifact);
85	    push_field(&mut out, "kernel", &d.kernel);
86	    push_field(&mut out, "engine", &d.engine);
87	    push_field(&mut out, "cases", &d.cases.to_string());
88	    push_field(&mut out, "fuel", &d.fuel.to_string());
89	    push_field(&mut out, "waiver-policy", &d.waiver_policy);
90	    // §11.2: when there are no waivers the value is EMPTY and the line is
91	    // STILL PRESENT — omitting it would make "no waivers" and "field absent"
92	    // the same bytes.
93	    push_field(&mut out, "waivers", &canonical_waivers(&d.waivers).join(","));
94	
95	    out.into_bytes()
96	}
97	
98	/// `campaignHash` (§11.3) — `SHA-256(campaignEncode(d))`, lowercase hex.
99	///
100	/// Deliberately a thin wrapper: it hashes the encoded bytes and interprets
101	/// nothing. Every normalization the identity depends on already happened in
102	/// [`campaign_encode`], so hashing that function's output by hand yields the
103	/// same digest.
104	pub fn campaign_hash(d: &CampaignDescription) -> String {
105	    sha256_hex(&campaign_encode(d))
106	}
107	
108	/// The raw 32-byte digest, for callers that want bytes rather than the §11
109	/// lowercase-hex rendering.
110	pub fn campaign_hash_bytes(d: &CampaignDescription) -> [u8; 32] {
111	    sha256(&campaign_encode(d))
112	}
113	
114	/// One `key=value` line: no spaces around `=`, single LF terminator.
115	fn push_field(out: &mut String, key: &str, value: &str) {
116	    out.push_str(key);
117	    out.push('=');
118	    out.push_str(value);
119	    out.push('\n');
120	}
121	
122	/// Canonicalize the `waivers` SET (§11.2), in the order the spec states:
123	/// collapse duplicates, THEN sort ascending as byte strings.
124	///
125	/// Duplicates COLLAPSE rather than being rejected — a description naming the
126	/// same waiver twice is meaningless, not invalid. (The two steps commute, but
127	/// they are written in the specified order rather than fused into a sorted set
128	/// so the code reads as §11.2 does.)
129	fn canonical_waivers(waivers: &[String]) -> Vec<&str> {
130	    let mut uniq: Vec<&str> = Vec::with_capacity(waivers.len());
131	    for w in waivers {
132	        if !uniq.iter().any(|seen| *seen == w.as_str()) {
133	            uniq.push(w.as_str());
134	        }
135	    }
136	    // "ASCENDING as byte strings" — compare the UTF-8 bytes, not chars and not
137	    // any decoded numeric value.
138	    uniq.sort_by(|a, b| a.as_bytes().cmp(b.as_bytes()));
139	    uniq
140	}
141	
142	impl CampaignDescription {
143	    /// Shape check for the §11.2 grammar, kept OFF the encoding path.
144	    ///
145	    /// §11.2 writes `artifact=<64 lowercase hex>` and keys waivers by mutant
146	    /// hash, but gives `campaignEncode` no error path, so this is offered as a
147	    /// separate obligation a caller may discharge. It also rejects LF and CR in
148	    /// the free-form values (`kernel`, `engine`, `waiver-policy`): §11.2
149	    /// justifies line framing by noting a value containing `=` cannot shift the
150	    /// parse, but says nothing about a value containing the line terminator
151	    /// itself — see DIVERGENCES.md.
152	    pub fn validate(&self) -> Result<(), String> {
153	        if !is_hash_hex(&self.artifact) {
154	            return Err(format!(
155	                "artifact must be 64 lowercase hex digits, got {:?}",
156	                self.artifact
157	            ));
158	        }
159	        for w in &self.waivers {
160	            if !is_hash_hex(w) {
161	                return Err(format!(
162	                    "waiver must be 64 lowercase hex digits, got {:?}",
163	                    w
164	                ));
165	            }
166	        }
167	        for (name, v) in [
168	            ("kernel", &self.kernel),
169	            ("engine", &self.engine),
170	            ("waiver-policy", &self.waiver_policy),
171	        ] {
172	            if v.contains('\n') || v.contains('\r') {
173	                return Err(format!("{} must not contain a line terminator", name));
174	            }
175	        }
176	        Ok(())
177	    }
178	}
179	
180	fn is_hash_hex(s: &str) -> bool {
181	    s.len() == 64
182	        && s.bytes()
183	            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
184	}
