//! Ed25519 (RFC 8032), the signature scheme SPEC §8.4 and §8.6 are stated over.
//!
//! §8.6 needs exactly one operation — "`author_sig` is a valid signature under
//! `author_pubkey` over the envelope's exact bytes" — but a verifier that cannot
//! also SIGN cannot be tested against anything except pre-baked vectors, so both
//! directions are here.
//!
//! Implemented by hand on the `num-bigint` already used for `Int` (§3) and the
//! `sha2` already used for object identity (§1), following `crypto.rs`'s
//! precedent for `hmac-sha256`: no new dependency, and the library stays pure
//! computation so the wasm build's surface is unchanged. Field arithmetic is
//! arbitrary-precision modular arithmetic rather than packed limbs — a
//! publication verifies a handful of signatures, never a stream of them, so
//! clarity beats throughput here and the whole curve layer is auditable against
//! RFC 8032 line by line.
//!
//! ## What SPEC does NOT pin, and this module therefore decides
//!
//! "A valid Ed25519 signature" names a scheme with several incompatible
//! verification conventions, and the choice is OBSERVABLE between kernels: a
//! signature one kernel accepts and another rejects makes a journal
//! conformant-or-not depending on who reads it. The choices made here, all
//! recorded in DIVERGENCES.md:
//!
//!   * the **cofactorless** verification equation `[S]B = R + [k]A` (RFC 8032
//!     §5.1.7's first, non-batch form), not the cofactored `[8][S]B = [8]R +
//!     [8][k]A`;
//!   * `S` MUST be canonical — reduced mod `L`. This is what makes a signature
//!     non-malleable: without it, `S + L` is a second valid signature over the
//!     same message, and an audit trail whose entries admit two distinct valid
//!     signatures cannot be quoted as "the" author statement;
//!   * `A` and `R` MUST be canonically encoded — `y < p`, and the sign bit of a
//!     zero `x` must be 0. A non-canonical encoding is a second byte spelling of
//!     one point, which is the same failure §8.6.1 rejects uppercase hex for;
//!   * small-order `A` is NOT rejected. RFC 8032 does not require it, and a
//!     public key is an identity here (§8.4: "a principal IS an Ed25519
//!     keypair"), so refusing one is a policy decision, not a signature check.

use num_bigint::{BigInt, Sign};
use sha2::{Digest, Sha512};
use std::sync::OnceLock;

/// A point in extended twisted-Edwards coordinates: `x = X/Z`, `y = Y/Z`,
/// `T = XY/Z`. Projective so that scalar multiplication needs no inversion per
/// step; the single inversion happens in [`encode`].
#[derive(Clone, Debug)]
struct Point {
    x: BigInt,
    y: BigInt,
    z: BigInt,
    t: BigInt,
}

/// Curve constants (RFC 8032 §5.1). Built once; every value here is derived
/// from the definitions rather than transcribed, so a typo in a long decimal
/// literal cannot silently move the curve.
struct Curve {
    /// The field prime, 2^255 - 19.
    p: BigInt,
    /// The curve parameter d = -121665/121666 mod p.
    d: BigInt,
    /// The prime order of the base point's subgroup, 2^252 + 27742...493.
    l: BigInt,
    /// A square root of -1 mod p, used to recover x when the first candidate
    /// root is off by that factor.
    sqrt_m1: BigInt,
    /// The base point B = (x, 4/5) with x even.
    base: Point,
}

fn curve() -> &'static Curve {
    static C: OnceLock<Curve> = OnceLock::new();
    C.get_or_init(|| {
        let one = BigInt::from(1u32);
        let p = (&one << 255u32) - BigInt::from(19u32);
        let d = fe_mul(
            &fe(&-BigInt::from(121665u32), &p),
            &fe_inv(&BigInt::from(121666u32), &p),
            &p,
        );
        let l = (&one << 252u32)
            + "27742317777372353535851937790883648493"
                .parse::<BigInt>()
                .expect("group order literal is decimal");
        // sqrt(-1) = 2^((p-1)/4) mod p.
        let sqrt_m1 = BigInt::from(2u32).modpow(&((&p - &one) / BigInt::from(4u32)), &p);
        // B's y is 4/5; its x is the even root (RFC 8032 §5.1's B).
        let by = fe_mul(&BigInt::from(4u32), &fe_inv(&BigInt::from(5u32), &p), &p);
        let bx = recover_x(&by, 0, &p, &d, &sqrt_m1).expect("4/5 is a curve y-coordinate");
        let base = affine(bx, by, &p);
        Curve { p, d, l, sqrt_m1, base }
    })
}

// ---------------------------------------------------------------------------
// field arithmetic (mod p)
// ---------------------------------------------------------------------------

/// Least non-negative residue. `num-bigint`'s `%` truncates toward zero, so a
/// negative operand needs the modulus added back.
fn fe(a: &BigInt, p: &BigInt) -> BigInt {
    let r = a % p;
    if r.sign() == Sign::Minus {
        r + p
    } else {
        r
    }
}

fn fe_add(a: &BigInt, b: &BigInt, p: &BigInt) -> BigInt {
    fe(&(a + b), p)
}

fn fe_sub(a: &BigInt, b: &BigInt, p: &BigInt) -> BigInt {
    fe(&(a - b), p)
}

fn fe_mul(a: &BigInt, b: &BigInt, p: &BigInt) -> BigInt {
    fe(&(a * b), p)
}

/// Inverse by Fermat: `a^(p-2) mod p`. `p` is prime and `a` is never 0 on any
/// path here (the only inversions are of 5, 121666, a `Z` coordinate — never
/// zero for a valid point — and a `v = d*y^2 + 1`, which is nonzero because
/// `-1/d` is not a square mod p).
fn fe_inv(a: &BigInt, p: &BigInt) -> BigInt {
    fe(a, p).modpow(&(p - BigInt::from(2u32)), p)
}

// ---------------------------------------------------------------------------
// group arithmetic
// ---------------------------------------------------------------------------

fn identity(p: &BigInt) -> Point {
    let _ = p;
    Point {
        x: BigInt::from(0u32),
        y: BigInt::from(1u32),
        z: BigInt::from(1u32),
        t: BigInt::from(0u32),
    }
}

fn affine(x: BigInt, y: BigInt, p: &BigInt) -> Point {
    let t = fe_mul(&x, &y, p);
    Point { x, y, z: BigInt::from(1u32), t }
}

/// The unified addition law for a = -1 twisted Edwards curves
/// (add-2008-hwcd-3). It is complete on this curve, so doubling is `add(p, p)`
/// and there is no exceptional case to branch on — which is also why there is
/// no separate `double`: a second formula is a second chance to be wrong.
fn add(a: &Point, b: &Point, c: &Curve) -> Point {
    let p = &c.p;
    let aa = fe_mul(&fe_sub(&a.y, &a.x, p), &fe_sub(&b.y, &b.x, p), p);
    let bb = fe_mul(&fe_add(&a.y, &a.x, p), &fe_add(&b.y, &b.x, p), p);
    let cc = fe_mul(
        &fe_mul(&fe_mul(&BigInt::from(2u32), &c.d, p), &a.t, p),
        &b.t,
        p,
    );
    let dd = fe_mul(&fe_mul(&BigInt::from(2u32), &a.z, p), &b.z, p);
    let e = fe_sub(&bb, &aa, p);
    let f = fe_sub(&dd, &cc, p);
    let g = fe_add(&dd, &cc, p);
    let h = fe_add(&bb, &aa, p);
    Point {
        x: fe_mul(&e, &f, p),
        y: fe_mul(&g, &h, p),
        t: fe_mul(&e, &h, p),
        z: fe_mul(&f, &g, p),
    }
}

/// `[k]P`, most-significant bit first. `k` is a scalar mod L, so its bit length
/// is data-independent in the only sense that matters here (this code verifies
/// public statements; there is no secret scalar on the verification path, and
/// signing is only used by tests and tools).
fn scalar_mul(k: &BigInt, point: &Point, c: &Curve) -> Point {
    let mut acc = identity(&c.p);
    let bits = k.bits();
    let mut i = bits;
    while i > 0 {
        i -= 1;
        acc = add(&acc, &acc, c);
        if bit(k, i) {
            acc = add(&acc, point, c);
        }
    }
    acc
}

fn bit(k: &BigInt, i: u64) -> bool {
    // BigInt has no bit accessor that is stable across versions; shift instead.
    let shifted = k >> i;
    (&shifted % BigInt::from(2u32)) != BigInt::from(0u32)
}

/// Projective equality: `x1/z1 == x2/z2` and `y1/z1 == y2/z2`, cross-multiplied
/// so no inversion is needed.
fn point_eq(a: &Point, b: &Point, p: &BigInt) -> bool {
    fe_mul(&a.x, &b.z, p) == fe_mul(&b.x, &a.z, p)
        && fe_mul(&a.y, &b.z, p) == fe_mul(&b.y, &a.z, p)
}

/// Recover `x` from `y` and the sign bit: `x^2 = (y^2 - 1)/(d*y^2 + 1)`.
/// `None` when that has no square root (the y is not on the curve) or when the
/// encoding is the non-canonical `x = 0` with sign bit 1.
fn recover_x(y: &BigInt, sign: u8, p: &BigInt, d: &BigInt, sqrt_m1: &BigInt) -> Option<BigInt> {
    let y2 = fe_mul(y, y, p);
    let u = fe_sub(&y2, &BigInt::from(1u32), p);
    let v = fe_add(&fe_mul(d, &y2, p), &BigInt::from(1u32), p);
    let w = fe_mul(&u, &fe_inv(&v, p), p);
    // The candidate root: w^((p+3)/8).
    let mut x = w.modpow(&((p + BigInt::from(3u32)) / BigInt::from(8u32)), p);
    if fe_mul(&x, &x, p) != w {
        x = fe_mul(&x, sqrt_m1, p);
    }
    if fe_mul(&x, &x, p) != w {
        return None; // not a square: y is not the y-coordinate of any point
    }
    let zero = BigInt::from(0u32);
    if x == zero && sign == 1 {
        // RFC 8032 §5.1.3: x = 0 with x_0 = 1 is a second spelling of the same
        // point, and decoding MUST fail rather than fold it.
        return None;
    }
    if (&x % BigInt::from(2u32) != zero) != (sign == 1) {
        x = fe_sub(p, &x, p);
    }
    Some(x)
}

// ---------------------------------------------------------------------------
// encodings
// ---------------------------------------------------------------------------

/// Little-endian 32-byte integer.
fn le32(bytes: &[u8]) -> BigInt {
    let mut n = BigInt::from(0u32);
    for b in bytes.iter().rev() {
        n = (n << 8u32) + BigInt::from(*b);
    }
    n
}

fn to_le32(n: &BigInt) -> [u8; 32] {
    let mut out = [0u8; 32];
    let mut v = n.clone();
    let byte = BigInt::from(256u32);
    for slot in out.iter_mut() {
        let r = &v % &byte;
        // r is non-negative: callers only pass reduced values.
        *slot = r.to_u32_digits().1.first().copied().unwrap_or(0) as u8;
        v /= &byte;
    }
    out
}

/// Point compression (RFC 8032 §5.1.2): the 255-bit `y`, with `x`'s low bit in
/// the top bit.
fn encode_point(point: &Point, p: &BigInt) -> [u8; 32] {
    let zi = fe_inv(&point.z, p);
    let x = fe_mul(&point.x, &zi, p);
    let y = fe_mul(&point.y, &zi, p);
    let mut out = to_le32(&y);
    if &x % BigInt::from(2u32) != BigInt::from(0u32) {
        out[31] |= 0x80;
    }
    out
}

/// Strict point decompression. Rejects a non-canonical `y` (>= p) as well as a
/// y that is not on the curve — both are byte strings that are not the unique
/// encoding of any point.
fn decode_point(bytes: &[u8], c: &Curve) -> Option<Point> {
    if bytes.len() != 32 {
        return None;
    }
    let sign = bytes[31] >> 7;
    let mut ybytes = [0u8; 32];
    ybytes.copy_from_slice(bytes);
    ybytes[31] &= 0x7f;
    let y = le32(&ybytes);
    if y >= c.p {
        return None; // non-canonical: a second spelling of y - p
    }
    let x = recover_x(&y, sign, &c.p, &c.d, &c.sqrt_m1)?;
    Some(affine(x, y, &c.p))
}

fn sha512(parts: &[&[u8]]) -> [u8; 64] {
    let mut h = Sha512::new();
    for part in parts {
        h.update(part);
    }
    let digest = h.finalize();
    let mut out = [0u8; 64];
    out.copy_from_slice(&digest);
    out
}

// ---------------------------------------------------------------------------
// the public surface
// ---------------------------------------------------------------------------

/// Verify an Ed25519 signature. `pubkey` is 32 bytes, `sig` is 64.
///
/// The conventions (cofactorless equation, canonical `S`, canonical `A`/`R`,
/// small-order `A` allowed) are the module-level ones; see the header for why
/// each is a choice SPEC leaves open.
pub fn verify(pubkey: &[u8], msg: &[u8], sig: &[u8]) -> bool {
    if pubkey.len() != 32 || sig.len() != 64 {
        return false;
    }
    let c = curve();
    let s = le32(&sig[32..64]);
    if s >= c.l {
        return false; // non-canonical S: malleable, so not "the" signature
    }
    let a = match decode_point(pubkey, c) {
        Some(a) => a,
        None => return false,
    };
    let r = match decode_point(&sig[0..32], c) {
        Some(r) => r,
        None => return false,
    };
    let k = fe(&le32_wide(&sha512(&[&sig[0..32], pubkey, msg])), &c.l);
    // [S]B == R + [k]A
    let lhs = scalar_mul(&s, &c.base, c);
    let rhs = add(&r, &scalar_mul(&k, &a, c), c);
    point_eq(&lhs, &rhs, &c.p)
}

/// Little-endian integer over an arbitrary-width buffer (the 64-byte SHA-512
/// output, before reduction mod L).
fn le32_wide(bytes: &[u8]) -> BigInt {
    let mut n = BigInt::from(0u32);
    for b in bytes.iter().rev() {
        n = (n << 8u32) + BigInt::from(*b);
    }
    n
}

/// The public key of a 32-byte seed.
pub fn public_key(seed: &[u8]) -> Option<[u8; 32]> {
    if seed.len() != 32 {
        return None;
    }
    let c = curve();
    let (a, _) = expand_seed(seed);
    Some(encode_point(&scalar_mul(&a, &c.base, c), &c.p))
}

/// Sign with a 32-byte seed (RFC 8032 §5.1.6). Deterministic: no randomness,
/// which is what lets a signing test be a fixture rather than a probability.
pub fn sign(seed: &[u8], msg: &[u8]) -> Option<[u8; 64]> {
    if seed.len() != 32 {
        return None;
    }
    let c = curve();
    let (a, prefix) = expand_seed(seed);
    let pubkey = encode_point(&scalar_mul(&a, &c.base, c), &c.p);
    let r = fe(&le32_wide(&sha512(&[&prefix, msg])), &c.l);
    let rp = encode_point(&scalar_mul(&r, &c.base, c), &c.p);
    let k = fe(&le32_wide(&sha512(&[&rp, &pubkey, msg])), &c.l);
    let s = fe(&(r + k * &a), &c.l);
    let mut out = [0u8; 64];
    out[0..32].copy_from_slice(&rp);
    out[32..64].copy_from_slice(&to_le32(&s));
    Some(out)
}

/// RFC 8032 §5.1.5: hash the seed, clamp the low half into the scalar's
/// required shape, keep the high half as the nonce prefix.
fn expand_seed(seed: &[u8]) -> (BigInt, [u8; 32]) {
    let h = sha512(&[seed]);
    let mut a = [0u8; 32];
    a.copy_from_slice(&h[0..32]);
    a[0] &= 248;
    a[31] &= 127;
    a[31] |= 64;
    let mut prefix = [0u8; 32];
    prefix.copy_from_slice(&h[32..64]);
    (le32(&a), prefix)
}

// ---------------------------------------------------------------------------
// hex, the form SPEC §8.4/§8.6 carry keys and signatures in
// ---------------------------------------------------------------------------

/// Lowercase hex, the only rendering §8.6.3 admits.
pub fn to_hex(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
        s.push(char::from_digit((b & 0xf) as u32, 16).unwrap());
    }
    s
}

/// Decode LOWERCASE hex of exactly `n` bytes. Uppercase is rejected rather than
/// folded: §8.6 compares byte spellings, so accepting `AB` here would make a
/// field that fails §8.6.1's lowercase rule usable anyway.
pub fn from_hex_exact(s: &str, n: usize) -> Option<Vec<u8>> {
    if s.len() != n * 2 {
        return None;
    }
    let b = s.as_bytes();
    let mut out = Vec::with_capacity(n);
    for pair in b.chunks(2) {
        let hi = lower_hex_digit(pair[0])?;
        let lo = lower_hex_digit(pair[1])?;
        out.push(hi << 4 | lo);
    }
    Some(out)
}

fn lower_hex_digit(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        _ => None,
    }
}

// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    fn unhex(s: &str) -> Vec<u8> {
        from_hex_exact(s, s.len() / 2).expect("test vector is lowercase hex")
    }

    // RFC 8032 §7.1 test vectors. These check the whole stack at once: a wrong
    // base point, a wrong d, a wrong sqrt(-1) branch or a wrong scalar
    // reduction all fail here, which is why the constants above are derived
    // rather than transcribed — these vectors are the only transcription.
    const VECTORS: &[(&str, &str, &str, &str)] = &[
        (
            "TEST 1 (empty message)",
            "9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60",
            "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a",
            "",
        ),
        (
            "TEST 2 (one byte)",
            "4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb",
            "3d4017c3e843895a92b70aa74d1b7ebc9c982ccf2ec4968cc0cd55f12af4660c",
            "72",
        ),
        (
            "TEST 3 (two bytes)",
            "c5aa8df43f9f837bedb7442f31dcb7b166d38535076f094b85ce3a2e0b4458f7",
            "fc51cd8e6218a1a38da47ed00230f0580816ed13ba3303ac5deb911548908025",
            "af82",
        ),
    ];

    const SIGS: &[&str] = &[
        "e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e065224901555fb8821590a33bacc61e39701cf9b46bd25bf5f0595bdd268c158ff1a4dcffb2",
        "92a009a9f0d4cab8720e820b5f642540a2b27b5416503f8fb3762223ebdb69da085ac1e43e15996e458f3613d0f11d8c387b2eaeb4302aeeb00d291612bb0c00",
        "6291d657deec24024827e69c3abe01a30ce548a284743a445e3680d7db5ac3ac18ff9b538d16f290ae67f760984dc6594a7c15e9716ed28dc027beceea1ec40a",
    ];

    #[test]
    fn rfc8032_public_keys() {
        for (label, seed, pk, _) in VECTORS {
            assert_eq!(
                to_hex(&public_key(&unhex(seed)).unwrap()),
                *pk,
                "{}: public key derivation",
                label
            );
        }
    }

    #[test]
    fn rfc8032_signatures_reproduce() {
        for (i, (label, seed, _, msg)) in VECTORS.iter().enumerate() {
            let sig = sign(&unhex(seed), &unhex(msg)).unwrap();
            assert_eq!(to_hex(&sig), SIGS[i], "{}: signature bytes", label);
        }
    }

    #[test]
    fn rfc8032_signatures_verify() {
        for (i, (label, _, pk, msg)) in VECTORS.iter().enumerate() {
            assert!(
                verify(&unhex(pk), &unhex(msg), &unhex(SIGS[i])),
                "{}: verify",
                label
            );
        }
    }

    #[test]
    fn a_flipped_message_byte_fails() {
        let (_, _, pk, _) = VECTORS[2];
        let mut msg = unhex("af82");
        msg[0] ^= 1;
        assert!(!verify(&unhex(pk), &msg, &unhex(SIGS[2])));
    }

    #[test]
    fn a_flipped_signature_byte_fails() {
        let (_, _, pk, msg) = VECTORS[1];
        for i in [0usize, 31, 32, 63] {
            let mut sig = unhex(SIGS[1]);
            sig[i] ^= 1;
            assert!(
                !verify(&unhex(pk), &unhex(msg), &sig),
                "flipping signature byte {} still verified",
                i
            );
        }
    }

    #[test]
    fn a_different_key_fails() {
        let (_, _, pk, msg) = VECTORS[0];
        let other = VECTORS[1].2;
        assert!(verify(&unhex(pk), &unhex(msg), &unhex(SIGS[0])));
        assert!(!verify(&unhex(other), &unhex(msg), &unhex(SIGS[0])));
    }

    #[test]
    fn wrong_lengths_fail_rather_than_panic() {
        let (_, _, pk, msg) = VECTORS[0];
        assert!(!verify(&unhex(pk)[..31], &unhex(msg), &unhex(SIGS[0])));
        assert!(!verify(&unhex(pk), &unhex(msg), &unhex(SIGS[0])[..63]));
        assert!(!verify(&[], &[], &[]));
        assert_eq!(public_key(&[]), None);
        assert_eq!(sign(&[1, 2, 3], b"x"), None);
    }

    /// Non-canonical S (`S + L`) MUST NOT verify: it is a second valid
    /// signature over one message, and §8.6 quotes "the" signature.
    #[test]
    fn malleable_signature_is_rejected() {
        let (_, _, pk, msg) = VECTORS[1];
        let sig = unhex(SIGS[1]);
        let c = curve();
        let s = le32(&sig[32..64]);
        let mut mauled = sig.clone();
        mauled[32..64].copy_from_slice(&to_le32(&(s + &c.l)));
        assert!(verify(&unhex(pk), &unhex(msg), &sig));
        assert!(
            !verify(&unhex(pk), &unhex(msg), &mauled),
            "S + L must not verify"
        );
    }

    /// A non-canonical `y` (y + p, when it fits in 255 bits) is a second
    /// spelling of one point and MUST NOT decode.
    #[test]
    fn non_canonical_point_encoding_is_rejected() {
        let c = curve();
        // y = 1 is the identity's y; y = 1 + p is the same residue, and fits.
        let y = BigInt::from(1u32) + &c.p;
        let bytes = to_le32(&y);
        assert!(decode_point(&bytes, c).is_none(), "y >= p must not decode");
        // ...while the canonical spelling does decode.
        assert!(decode_point(&to_le32(&BigInt::from(1u32)), c).is_some());
    }

    #[test]
    fn hex_helpers_reject_uppercase_and_bad_length() {
        assert_eq!(from_hex_exact("ABAB", 2), None);
        assert_eq!(from_hex_exact("abab", 2), Some(vec![0xab, 0xab]));
        assert_eq!(from_hex_exact("abab", 3), None);
        assert_eq!(from_hex_exact("abaz", 2), None);
        assert_eq!(to_hex(&[0x00, 0x0f, 0xf0, 0xff]), "000ff0ff");
    }

    /// The base point derived from y = 4/5 is on the curve and has order L —
    /// the two properties everything else rests on.
    #[test]
    fn base_point_has_prime_order() {
        let c = curve();
        let n = scalar_mul(&c.l, &c.base, c);
        assert!(
            point_eq(&n, &identity(&c.p), &c.p),
            "[L]B must be the identity"
        );
        let one = scalar_mul(&BigInt::from(1u32), &c.base, c);
        assert!(point_eq(&one, &c.base, &c.p));
    }
}

