#[cfg(test)]
mod tests {
    use super::*;

    const A64: &str = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
    const B64: &str = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
    const C64: &str = "cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc";

    fn first() -> Envelope {
        Envelope::first(OP_PUT, "double", A64, C64)
    }

    fn repoint() -> Envelope {
        Envelope::repoint(OP_PUT, "double", B64, A64, 1, C64)
    }

    fn enc(e: &Envelope) -> String {
        String::from_utf8(e.encode().expect("valid envelope")).unwrap()
    }

    // -- §8.6.1 encoding ------------------------------------------------------

    #[test]
    fn encoding_is_version_line_then_six_fields() {
        let s = enc(&first());
        assert_eq!(
            s,
            format!(
                "oath-publish/1\nop=put\nname=double\nartifact={}\nparent=-\nparent_rev=0\nauthor={}\n",
                A64, C64
            )
        );
        assert!(s.ends_with('\n'));
        assert!(!s.ends_with("\n\n"), "no trailing blank line");
        assert!(!s.contains('\r'), "LF only, never CRLF");
        assert!(!s.contains(" = "), "no whitespace around =");
        let lines: Vec<&str> = s.trim_end_matches('\n').split('\n').collect();
        assert_eq!(lines.len(), 7);
        assert_eq!(lines[0], ENVELOPE_VERSION);
        let keys: Vec<&str> = lines[1..]
            .iter()
            .map(|l| l.split_once('=').unwrap().0)
            .collect();
        assert_eq!(keys, KEYS.to_vec());
    }

    #[test]
    fn the_sentinel_is_the_only_spelling_of_no_parent() {
        assert!(enc(&first()).contains("\nparent=-\n"));
        assert!(enc(&repoint()).contains(&format!("\nparent={}\n", A64)));
    }

    #[test]
    fn every_field_reaches_the_bytes() {
        let base = repoint();
        let mut variants = Vec::new();
        let mut v = base.clone();
        v.name = "triple".into();
        variants.push(v);
        let mut v = base.clone();
        v.artifact = C64.into();
        variants.push(v);
        let mut v = base.clone();
        v.parent = Some(B64.into());
        variants.push(v);
        let mut v = base.clone();
        v.parent_rev = BigUint::from(2u32);
        variants.push(v);
        let mut v = base.clone();
        v.author = A64.into();
        variants.push(v);
        for v in &variants {
            assert_ne!(enc(v), enc(&base), "a field change did not move the bytes");
        }
    }

    // -- §8.6.1 validation: each rule, in both directions ---------------------

    #[test]
    fn encoding_rejects_uppercase_hex() {
        for field in 0..3 {
            let mut e = repoint();
            let upper = A64.to_uppercase();
            match field {
                0 => e.artifact = upper,
                1 => e.parent = Some(upper),
                _ => e.author = upper,
            }
            assert!(e.encode().is_err(), "uppercase hex accepted in field {}", field);
        }
    }

    #[test]
    fn encoding_rejects_short_and_long_hex() {
        let mut e = repoint();
        e.artifact = "ab".into();
        assert!(e.encode().is_err());
        let mut e = repoint();
        e.artifact = format!("{}00", A64);
        assert!(e.encode().is_err());
    }

    #[test]
    fn encoding_rejects_a_non_put_op() {
        let mut e = first();
        e.op = "repoint".into();
        assert!(e.encode().is_err());
        let mut e = first();
        e.op = "PUT".into();
        assert!(e.encode().is_err());
        let mut e = first();
        e.op = String::new();
        assert!(e.encode().is_err());
    }

    #[test]
    fn encoding_rejects_control_characters_in_any_value() {
        for c in ['\n', '\r', '\t', '\u{0}', '\u{1f}', '\u{7f}'] {
            let mut e = first();
            e.name = format!("do{}uble", c);
            assert!(
                e.encode().is_err(),
                "U+{:04X} accepted in a value — it could inject a line",
                c as u32
            );
        }
        // The rule is over EVERY value, not just the free-form one.
        let mut e = first();
        e.op = "put\nop=put".into();
        assert!(e.encode().is_err());
    }

    #[test]
    fn the_sentinel_and_revision_zero_hold_iff_each_other() {
        // parent=- with a nonzero revision
        let mut e = first();
        e.parent_rev = BigUint::from(2u32);
        assert!(e.encode().is_err());
        // a parent hash with revision 0
        let mut e = repoint();
        e.parent_rev = BigUint::from(0u32);
        assert!(e.encode().is_err());
        // ...and the two agreeing cases both encode.
        assert!(first().encode().is_ok());
        assert!(repoint().encode().is_ok());
    }

    // -- §8.6.1 strict parsing ------------------------------------------------

    #[test]
    fn parse_round_trips_every_valid_shape() {
        for e in [first(), repoint()] {
            let bytes = e.encode().unwrap();
            let back = parse(&bytes).expect("valid envelope parses");
            assert_eq!(back, e);
            assert_eq!(back.encode().unwrap(), bytes);
        }
    }

    #[test]
    fn parse_rejects_a_missing_trailing_lf() {
        let mut bytes = first().encode().unwrap();
        bytes.pop();
        assert!(parse(&bytes).is_err());
    }

    #[test]
    fn parse_rejects_trailing_bytes() {
        for tail in [&b"x"[..], &b"\n"[..], &b"op=put\n"[..], &b"\0"[..]] {
            let mut bytes = first().encode().unwrap();
            bytes.extend_from_slice(tail);
            assert!(parse(&bytes).is_err(), "trailing {:?} accepted", tail);
        }
    }

    #[test]
    fn parse_rejects_unknown_missing_duplicated_and_reordered_keys() {
        let good = String::from_utf8(first().encode().unwrap()).unwrap();
        // unknown extra field
        assert!(parse(format!("{}extra=1\n", good).as_bytes()).is_err());
        // missing field (drop `author`)
        let missing: String = good
            .lines()
            .filter(|l| !l.starts_with("author="))
            .map(|l| format!("{}\n", l))
            .collect();
        assert!(parse(missing.as_bytes()).is_err());
        // duplicated field
        let dup = good.replace("op=put\n", "op=put\nop=put\n");
        assert!(parse(dup.as_bytes()).is_err());
        // reordered fields
        let reordered = format!(
            "oath-publish/1\nname=double\nop=put\nartifact={}\nparent=-\nparent_rev=0\nauthor={}\n",
            A64, C64
        );
        assert!(parse(reordered.as_bytes()).is_err());
        // a field line with no '='
        let noeq = good.replace("op=put\n", "op\n");
        assert!(parse(noeq.as_bytes()).is_err());
    }

    #[test]
    fn parse_rejects_a_wrong_or_missing_version_line() {
        let good = String::from_utf8(first().encode().unwrap()).unwrap();
        for bad in [
            "oath-publish/2",
            "oath-publish/1 ",
            "oath-publish",
            "OATH-PUBLISH/1",
            "",
        ] {
            let s = good.replacen(ENVELOPE_VERSION, bad, 1);
            assert!(parse(s.as_bytes()).is_err(), "version {:?} accepted", bad);
        }
    }

    #[test]
    fn parse_rejects_non_canonical_decimal_revisions() {
        let base = format!(
            "oath-publish/1\nop=put\nname=n\nartifact={}\nparent={}\nparent_rev=%\nauthor={}\n",
            A64, B64, C64
        );
        for bad in ["01", "+1", "1 ", " 1", "1.0", "-1", "", "0x1", "1_000", "١"] {
            let s = base.replace('%', bad);
            assert!(
                parse(s.as_bytes()).is_err(),
                "parent_rev={:?} accepted",
                bad
            );
        }
        // 0 is canonical, and so is a many-digit value.
        let zero = base.replace('%', "0").replace(&format!("parent={}", B64), "parent=-");
        assert!(parse(zero.as_bytes()).is_ok());
        let big = base.replace('%', "12345678901234567890123456789012345678901234567890");
        let parsed = parse(big.as_bytes()).expect("§8.6.1 nowhere bounds parent_rev");
        assert_eq!(
            parsed.parent_rev.to_str_radix(10),
            "12345678901234567890123456789012345678901234567890"
        );
        assert_eq!(parsed.encode().unwrap(), big.as_bytes());
    }

    #[test]
    fn parse_rejects_lenient_readings_that_would_re_encode_differently() {
        // Uppercase hex, the sentinel disagreements, and a non-put op are all
        // rejected at parse time too — §8.6.1 requires rejection on BOTH
        // encoding and verification.
        let cases = [
            format!(
                "oath-publish/1\nop=put\nname=n\nartifact={}\nparent=-\nparent_rev=0\nauthor={}\n",
                A64.to_uppercase(),
                C64
            ),
            format!(
                "oath-publish/1\nop=put\nname=n\nartifact={}\nparent=-\nparent_rev=2\nauthor={}\n",
                A64, C64
            ),
            format!(
                "oath-publish/1\nop=put\nname=n\nartifact={}\nparent={}\nparent_rev=0\nauthor={}\n",
                A64, B64, C64
            ),
            format!(
                "oath-publish/1\nop=delete\nname=n\nartifact={}\nparent=-\nparent_rev=0\nauthor={}\n",
                A64, C64
            ),
        ];
        for c in cases {
            assert!(parse(c.as_bytes()).is_err(), "accepted: {:?}", c);
        }
    }

    #[test]
    fn parse_rejects_non_utf8() {
        let mut bytes = first().encode().unwrap();
        bytes[20] = 0xff;
        assert!(parse(&bytes).is_err());
    }

    #[test]
    fn a_value_may_contain_an_equals_sign() {
        // Values are split at the FIRST '=', so a name containing '=' survives
        // the round trip. (§8.6.1 forbids control characters in a value, not
        // '='.)
        let mut e = first();
        e.name = "team/a=b".into();
        let bytes = e.encode().unwrap();
        assert_eq!(parse(&bytes).unwrap(), e);
    }

    // -- §8.6.2 the revision --------------------------------------------------

    fn entry(name: &str, kind: &str, status: &str, hash: &str, transition: Option<&str>) -> Entry {
        Entry {
            name: name.to_string(),
            kind: kind.to_string(),
            status: status.to_string(),
            hash: hash.to_string(),
            transition: transition.map(str::to_string),
            ..Entry::default()
        }
    }

    #[test]
    fn revision_counts_applied_transitions_not_accepted_entries() {
        let journal = vec![
            entry("d", "put", "accepted", A64, Some("applied")),
            entry("d", "put", "rejected", "", None),
            entry("d", "put", "blocked", B64, None),
            entry("d", "put", "pending", B64, None),
            // A falsified definition DOES bind its name.
            entry("d", "put", "falsified", B64, Some("applied")),
            // Another name's transitions are none of this name's business.
            entry("other", "put", "accepted", C64, Some("applied")),
        ];
        assert_eq!(name_revision(&journal, "d"), 2);
        assert_eq!(name_head(&journal, "d").as_deref(), Some(B64));
        assert_eq!(name_revision(&journal, "other"), 1);
        assert_eq!(name_revision(&journal, "never-published"), 0);
        assert_eq!(name_head(&journal, "never-published"), None);
    }

    #[test]
    fn revision_is_monotonic_across_an_aba_cycle() {
        // A -> B -> A: the parent hash becomes valid again, the revision does
        // not. This is the whole point of §8.6.2.
        let journal = vec![
            entry("d", "put", "accepted", A64, Some("applied")),
            entry("d", "put", "accepted", B64, Some("applied")),
            entry("d", "put", "accepted", A64, Some("applied")),
        ];
        assert_eq!(name_revision(&journal, "d"), 3);
        assert_eq!(name_head(&journal, "d").as_deref(), Some(A64));
        // The revision after the FIRST A is 1, so an old envelope naming
        // (parent=A, rev=1) no longer matches the current (parent=A, rev=3).
        let state = NameState::from_journal(&journal, "d");
        assert_eq!(state.rev, 3);
        let replay = Envelope::repoint(OP_PUT, "d", C64, A64, 1, C64);
        assert_ne!(replay.parent_rev, BigUint::from(state.rev));
    }

    #[test]
    fn the_pre_transition_fallback_reads_the_status() {
        // A journal written entirely before the field existed.
        let legacy = vec![
            entry("d", "put", "accepted", A64, None),
            entry("d", "put", "rejected", "", None),
            entry("d", "put", "falsified", B64, None),
            entry("d", "put", "blocked", C64, None),
            entry("d", "put", "pending", C64, None),
        ];
        assert_eq!(name_revision(&legacy, "d"), 2);
        assert_eq!(name_head(&legacy, "d").as_deref(), Some(B64));
    }

    #[test]
    fn the_fallback_stops_at_the_first_entry_carrying_transition() {
        // The upgrade point. Before it, absence means "consult the status";
        // from it on, absence means "did not apply" — otherwise a modern
        // non-applying `accepted` entry (a §8.5 prove-kind record, a §6.4
        // cross-check) would inflate the revision.
        let journal = vec![
            entry("d", "put", "accepted", A64, None),          // legacy: applied
            entry("d", "put", "accepted", B64, Some("applied")), // upgrade point
            entry("d", "prove", "accepted", B64, None),        // modern: NOT applied
            entry("d", "cross", "accepted", B64, None),        // modern: NOT applied
        ];
        assert_eq!(name_revision(&journal, "d"), 2);
        assert_eq!(legacy_prefix_len(&journal), 1);
    }

    #[test]
    fn a_transition_value_other_than_applied_does_not_count() {
        let journal = vec![
            entry("d", "put", "accepted", A64, Some("applied")),
            entry("d", "put", "accepted", B64, Some("deferred")),
        ];
        assert_eq!(name_revision(&journal, "d"), 1);
        assert_eq!(name_head(&journal, "d").as_deref(), Some(A64));
    }

    // -- §8.6.3/§8.6.4 verification ------------------------------------------

    const SEED: [u8; 32] = [7u8; 32];

    fn signed_entry() -> (Entry, String) {
        let author = crate::ed25519::to_hex(&crate::ed25519::public_key(&SEED).unwrap());
        let env = Envelope::repoint(OP_PUT, "double", B64, A64, 1, &author);
        let bytes = env.encode().unwrap();
        let sig = crate::ed25519::sign(&SEED, &bytes).unwrap();
        let entry = Entry {
            name: "double".into(),
            kind: "put".into(),
            status: "accepted".into(),
            hash: B64.into(),
            prev: A64.into(),
            transition: Some(TRANSITION_APPLIED.into()),
            envelope: bytes,
            author_pubkey: author.clone(),
            author_sig: crate::ed25519::to_hex(&sig),
        };
        (entry, author)
    }

    #[test]
    fn a_well_formed_signed_entry_verifies() {
        let (entry, _) = signed_entry();
        assert_eq!(verify_entry_publication(&entry), Ok(()));
        assert_eq!(verify_journal_publications(&[entry]), Ok(()));
    }

    #[test]
    fn an_entry_with_none_of_the_three_fields_imposes_no_obligation() {
        let e = entry("d", "put", "accepted", A64, Some("applied"));
        assert_eq!(verify_entry_publication(&e), Ok(()));
    }

    #[test]
    fn any_one_of_the_three_alone_is_rejected() {
        let (good, _) = signed_entry();
        for drop in 0..3 {
            let mut e = good.clone();
            match drop {
                0 => e.envelope = Vec::new(),
                1 => e.author_pubkey = String::new(),
                _ => e.author_sig = String::new(),
            }
            assert!(
                verify_entry_publication(&e).is_err(),
                "a partial publication (dropped {}) was accepted as unattributed",
                drop
            );
        }
    }

    #[test]
    fn a_mismatched_author_pubkey_is_rejected() {
        let (good, _) = signed_entry();
        let other = crate::ed25519::to_hex(&crate::ed25519::public_key(&[9u8; 32]).unwrap());
        let mut e = good.clone();
        e.author_pubkey = other;
        assert!(verify_entry_publication(&e).is_err());
    }

    /// The signature is checked against the PERSISTED bytes. A store that
    /// re-encoded the envelope — even to something this kernel considers
    /// canonical — must fail, because the persisted bytes are the statement.
    #[test]
    fn a_re_encoded_envelope_fails_the_signature_check() {
        let (good, _) = signed_entry();
        let mut e = good.clone();
        // A "normalization" that changes nothing semantically: CRLF framing.
        e.envelope = String::from_utf8(good.envelope.clone())
            .unwrap()
            .replace('\n', "\r\n")
            .into_bytes();
        assert!(verify_entry_publication(&e).is_err());
        // ...and one that changes only a byte the signature covers.
        let mut e = good.clone();
        let last = e.envelope.len() - 2;
        e.envelope[last] = b'b';
        assert!(verify_entry_publication(&e).is_err());
    }

    #[test]
    fn a_transition_the_author_did_not_sign_is_a_hard_failure() {
        let (good, _) = signed_entry();
        // name
        let mut e = good.clone();
        e.name = "triple".into();
        assert!(verify_entry_publication(&e).is_err());
        // hash (the artifact)
        let mut e = good.clone();
        e.hash = C64.into();
        assert!(verify_entry_publication(&e).is_err());
        // prev (the parent)
        let mut e = good.clone();
        e.prev = C64.into();
        assert!(verify_entry_publication(&e).is_err());
        // prev emptied: the entry claims a first publication the author did not
        // sign
        let mut e = good.clone();
        e.prev = String::new();
        assert!(verify_entry_publication(&e).is_err());
    }

    #[test]
    fn an_empty_prev_corresponds_to_the_sentinel() {
        let author = crate::ed25519::to_hex(&crate::ed25519::public_key(&SEED).unwrap());
        let env = Envelope::first(OP_PUT, "double", B64, &author);
        let bytes = env.encode().unwrap();
        let e = Entry {
            name: "double".into(),
            kind: "put".into(),
            status: "accepted".into(),
            hash: B64.into(),
            prev: String::new(),
            transition: Some(TRANSITION_APPLIED.into()),
            envelope: bytes.clone(),
            author_pubkey: author.clone(),
            author_sig: crate::ed25519::to_hex(&crate::ed25519::sign(&SEED, &bytes).unwrap()),
        };
        assert_eq!(verify_entry_publication(&e), Ok(()));
    }

    #[test]
    fn a_malformed_hex_key_or_signature_is_rejected_not_panicked() {
        let (good, _) = signed_entry();
        let mut e = good.clone();
        e.author_pubkey = good.author_pubkey.to_uppercase();
        assert!(verify_entry_publication(&e).is_err());
        let mut e = good.clone();
        e.author_sig = "zz".repeat(64);
        assert!(verify_entry_publication(&e).is_err());
        let mut e = good.clone();
        e.author_sig = "ab".into();
        assert!(verify_entry_publication(&e).is_err());
    }

    // -- §8.6.4's store-side preconditions -----------------------------------

    #[test]
    fn a_store_accepts_only_a_statement_by_the_authenticated_principal() {
        let author = crate::ed25519::to_hex(&crate::ed25519::public_key(&SEED).unwrap());
        let env = Envelope::repoint(OP_PUT, "double", B64, A64, 1, &author);
        let bytes = env.encode().unwrap();
        let sig = crate::ed25519::to_hex(&crate::ed25519::sign(&SEED, &bytes).unwrap());
        let current = NameState { head: Some(A64.into()), rev: 1 };

        assert!(accept_publication(&bytes, &sig, &author, B64, &current).is_ok());

        // A DIFFERENT authenticated principal replaying someone else's valid
        // statement: the signature is genuine, the principal is not the signer.
        let other = crate::ed25519::to_hex(&crate::ed25519::public_key(&[9u8; 32]).unwrap());
        assert!(accept_publication(&bytes, &sig, &other, B64, &current).is_err());
    }

    #[test]
    fn a_store_recomputes_the_artifact_hash() {
        let author = crate::ed25519::to_hex(&crate::ed25519::public_key(&SEED).unwrap());
        let env = Envelope::repoint(OP_PUT, "double", B64, A64, 1, &author);
        let bytes = env.encode().unwrap();
        let sig = crate::ed25519::to_hex(&crate::ed25519::sign(&SEED, &bytes).unwrap());
        let current = NameState { head: Some(A64.into()), rev: 1 };
        // The store elaborated the submitted content to something else.
        assert!(accept_publication(&bytes, &sig, &author, C64, &current).is_err());
    }

    #[test]
    fn a_store_requires_the_signed_parent_and_revision_to_be_current() {
        let author = crate::ed25519::to_hex(&crate::ed25519::public_key(&SEED).unwrap());
        let env = Envelope::repoint(OP_PUT, "double", B64, A64, 1, &author);
        let bytes = env.encode().unwrap();
        let sig = crate::ed25519::to_hex(&crate::ed25519::sign(&SEED, &bytes).unwrap());

        // Right parent, stale revision — the A -> B -> A replay.
        let aba = NameState { head: Some(A64.into()), rev: 3 };
        assert!(accept_publication(&bytes, &sig, &author, B64, &aba).is_err());
        // Wrong parent.
        let moved = NameState { head: Some(C64.into()), rev: 1 };
        assert!(accept_publication(&bytes, &sig, &author, B64, &moved).is_err());
        // Never published, but the envelope names a parent.
        assert!(
            accept_publication(&bytes, &sig, &author, B64, &NameState::unpublished()).is_err()
        );
    }

    #[test]
    fn a_first_publication_matches_an_unpublished_name() {
        let author = crate::ed25519::to_hex(&crate::ed25519::public_key(&SEED).unwrap());
        let env = Envelope::first(OP_PUT, "fresh", B64, &author);
        let bytes = env.encode().unwrap();
        let sig = crate::ed25519::to_hex(&crate::ed25519::sign(&SEED, &bytes).unwrap());
        assert!(
            accept_publication(&bytes, &sig, &author, B64, &NameState::unpublished()).is_ok()
        );
        // ...and not a name that already has a value.
        let current = NameState { head: Some(A64.into()), rev: 1 };
        assert!(accept_publication(&bytes, &sig, &author, B64, &current).is_err());
    }
}

