//! Signed publication — the author's statement (SPEC §8.6).
//!
//! §8.4 signs a journal ENTRY, which seals custody. §8.6 signs a PUBLICATION
//! ENVELOPE, which is the author's own statement about a transition and is
//! persisted verbatim, so authorship is checkable without trusting the store.
//! This module implements the three pure obligations §8.6 states:
//!
//! ```text
//! encode : Envelope -> bytes            (§8.6.1, canonical, MUST reject invalid)
//! parse  : bytes    -> Envelope         (§8.6.1, strict, re-encodes to input)
//! verify : Entry    -> ()               (§8.6.4, the five MUST conditions)
//! ```
//!
//! plus the revision rule (§8.6.2) and the store-side precondition set
//! (§8.6.4's second half). It stays pure computation — no filesystem, no clock,
//! no process — because oathrs has no store: a journal reaches these functions
//! as a slice of already-parsed [`Entry`] values, whatever produced them.
//!
//! ## Why every rule here is a byte rule
//!
//! The envelope bytes are what a signature is computed over. A kernel that
//! encodes one byte differently still produces CORRECT signatures that STOP
//! VERIFYING elsewhere — the failure mode §8.6.3 calls out ("the signature
//! would remain correct and stop verifying") and the reason §8.6.1's rules are
//! normative rather than advisory. So: no normalization anywhere on the
//! encoding path, no lenient parsing, and the re-encode check in [`parse`] is
//! not optional.
//!
//! Contrast with campaign identity (§11.2), whose `campaignEncode` is TOTAL —
//! §11 gives it no error path, so shape checking lives in an off-path
//! `validate()`. §8.6.1 says the opposite in as many words: "MUST reject an
//! envelope, **on both encoding and verification**". Hence [`Envelope::encode`]
//! returns a `Result` and there is no way to emit a malformed envelope from this
//! module.

use crate::ed25519;
use num_bigint::BigUint;

/// The version line (§8.6.1). Inside the signed bytes on purpose: a signature
/// under one format version can never be read as one under another.
pub const ENVELOPE_VERSION: &str = "oath-publish/1";

/// The only operation this version defines (§8.6.1).
pub const OP_PUT: &str = "put";

/// The `parent` sentinel meaning "the name had no previous value" (§8.6.1).
pub const PARENT_NONE: &str = "-";

/// The `transition` value that marks an APPLIED transition (§8.6.3).
pub const TRANSITION_APPLIED: &str = "applied";

/// The six field keys, in the normative order (§8.6.1). Order is identity here:
/// reordering forks every signature.
pub const KEYS: [&str; 6] = ["op", "name", "artifact", "parent", "parent_rev", "author"];

/// A publication envelope (§8.6.1).
///
/// Only what the AUTHOR controls: the name, the artifact, and the transition.
/// Deliberately no `status`, `guarantee`, `termination` or policy outcome —
/// §8.6 forbids covering store-derived verdicts, since an author cannot predict
/// them and a signature over them would make a policy decision
/// indistinguishable from a forgery.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Envelope {
    /// `op` — `put` in this version.
    pub op: String,
    /// The name being repointed. §8.6.1 constrains it only by the control-
    /// character rule; see DIVERGENCES.md on what that does and does not forbid.
    pub name: String,
    /// Content hash of the object being published: 64 lowercase hex.
    pub artifact: String,
    /// The name's current value: `Some(hash)`, or `None` for the `-` sentinel
    /// meaning the name had no previous value.
    ///
    /// Modelled as an `Option` rather than a `String` so the sentinel cannot be
    /// confused with a hash and cannot be spelled two ways.
    pub parent: Option<String>,
    /// The name's current revision (§8.6.2) — the number of journal entries that
    /// have APPLIED A TRANSITION to this name.
    ///
    /// A `BigUint`, not a `u64`: §8.6.1 says "a non-negative integer in
    /// canonical decimal" and nowhere bounds it, so a kernel that rejected a
    /// 30-digit revision would be rejecting an envelope §8.6.1 admits. See
    /// DIVERGENCES.md — this is UNTESTED by any fixture.
    pub parent_rev: BigUint,
    /// The signing key that makes this statement: 64 lowercase hex of a 32-byte
    /// Ed25519 public key.
    pub author: String,
}

impl Envelope {
    /// A first publication: no parent, revision 0. The two always agree by
    /// construction (§8.6.1's if-and-only-if).
    pub fn first(op: &str, name: &str, artifact: &str, author: &str) -> Envelope {
        Envelope {
            op: op.to_string(),
            name: name.to_string(),
            artifact: artifact.to_string(),
            parent: None,
            parent_rev: BigUint::from(0u32),
            author: author.to_string(),
        }
    }

    /// A repoint of a name that already has a value at revision `rev`.
    pub fn repoint(
        op: &str,
        name: &str,
        artifact: &str,
        parent: &str,
        rev: u64,
        author: &str,
    ) -> Envelope {
        Envelope {
            op: op.to_string(),
            name: name.to_string(),
            artifact: artifact.to_string(),
            parent: Some(parent.to_string()),
            parent_rev: BigUint::from(rev),
            author: author.to_string(),
        }
    }

    /// The canonical bytes (§8.6.1): the version line, then exactly six
    /// LF-terminated `key=value` lines in the fixed order. No other whitespace,
    /// no trailing content, no optional field.
    ///
    /// Rejects rather than emitting a non-canonical envelope: §8.6.1 requires
    /// rejection "on both encoding and verification".
    pub fn encode(&self) -> Result<Vec<u8>, String> {
        self.validate()?;
        Ok(self.encode_raw())
    }

    /// The bytes, with no validation. Private on purpose: the only callers are
    /// [`Envelope::encode`] (after validating) and [`parse`]'s re-encode check
    /// (on an already-validated value). Nothing outside this module can produce
    /// unchecked envelope bytes.
    fn encode_raw(&self) -> Vec<u8> {
        let mut out = String::new();
        out.push_str(ENVELOPE_VERSION);
        out.push('\n');
        for (key, value) in KEYS.iter().zip(self.values()) {
            out.push_str(key);
            out.push('=');
            out.push_str(&value);
            out.push('\n');
        }
        out.into_bytes()
    }

    /// The six values, in `KEYS` order.
    fn values(&self) -> Vec<String> {
        vec![
            self.op.clone(),
            self.name.clone(),
            self.artifact.clone(),
            self.parent_field(),
            self.parent_rev.to_str_radix(10),
            self.author.clone(),
        ]
    }

    /// The `parent` field's text: the hash, or the `-` sentinel.
    pub fn parent_field(&self) -> String {
        match &self.parent {
            Some(h) => h.clone(),
            None => PARENT_NONE.to_string(),
        }
    }

    /// Every §8.6.1 rule, in the order the spec lists them. Each exists because
    /// its absence admits a second byte spelling of one statement.
    pub fn validate(&self) -> Result<(), String> {
        // "every value is free of LF, CR, and any character below 0x20 or equal
        // to 0x7F" — checked FIRST and over every value, because a value
        // carrying an LF would inject a line and the encoding would stop being
        // uniquely decodable, which no later check could detect.
        for (key, value) in KEYS.iter().zip(self.values()) {
            if let Some(bad) = value.chars().find(|c| is_forbidden(*c)) {
                return Err(format!(
                    "{}: value contains the control character U+{:04X}",
                    key, bad as u32
                ));
            }
        }
        if self.op != OP_PUT {
            return Err(format!(
                "op must be {:?} (the only operation in {}), got {:?}",
                OP_PUT, ENVELOPE_VERSION, self.op
            ));
        }
        // Uppercase hex MUST be rejected, not folded: the encoding is compared
        // as bytes, so `ABAB…` and `abab…` would be two different statements
        // about one artifact.
        if !is_hash_hex(&self.artifact) {
            return Err(format!(
                "artifact must be 64 lowercase hex characters, got {:?}",
                self.artifact
            ));
        }
        if let Some(parent) = &self.parent {
            if !is_hash_hex(parent) {
                return Err(format!(
                    "parent must be 64 lowercase hex characters or {:?}, got {:?}",
                    PARENT_NONE, parent
                ));
            }
        }
        // `parent` is `-` if and only if `parent_rev` is 0. Allowing the two to
        // disagree would let one envelope describe two different states.
        let rev_zero = self.parent_rev == BigUint::from(0u32);
        match (&self.parent, rev_zero) {
            (None, false) => {
                return Err(format!(
                    "parent is {:?} but parent_rev is {} — the sentinel holds iff the revision is 0",
                    PARENT_NONE,
                    self.parent_rev.to_str_radix(10)
                ))
            }
            (Some(_), true) => {
                return Err(
                    "parent names a hash but parent_rev is 0 — the sentinel holds iff the revision is 0"
                        .to_string(),
                )
            }
            _ => {}
        }
        if !is_hash_hex(&self.author) {
            return Err(format!(
                "author must be 64 lowercase hex characters, got {:?}",
                self.author
            ));
        }
        Ok(())
    }

    /// The 32-byte author key, or `None` when `author` is not 64 lowercase hex.
    pub fn author_key(&self) -> Option<Vec<u8>> {
        ed25519::from_hex_exact(&self.author, 32)
    }
}

/// §8.6.1's forbidden characters: LF, CR, anything below `0x20`, and `0x7F`.
///
/// Note what this does NOT forbid, because §8.6.1 does not: the C1 controls
/// `U+0080..U+009F`, and non-ASCII generally. The rule is stated over
/// CHARACTERS, so it is read as characters here. See DIVERGENCES.md.
fn is_forbidden(c: char) -> bool {
    c == '\n' || c == '\r' || (c as u32) < 0x20 || c == '\u{7f}'
}

/// 64 lowercase hex characters. Uppercase is rejected, not folded (§8.6.1).
fn is_hash_hex(s: &str) -> bool {
    s.len() == 64
        && s.bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

/// Canonical decimal (§8.6.1): non-negative, no leading zeros, no sign, no
/// spaces. `0` is canonical; `03` and `+3` are not.
fn parse_canonical_decimal(s: &str) -> Result<BigUint, String> {
    if s.is_empty() {
        return Err("parent_rev is empty; canonical decimal has at least one digit".to_string());
    }
    if !s.bytes().all(|b| b.is_ascii_digit()) {
        return Err(format!(
            "parent_rev must be canonical decimal (no sign, no spaces), got {:?}",
            s
        ));
    }
    if s.len() > 1 && s.starts_with('0') {
        return Err(format!(
            "parent_rev must be canonical decimal (no leading zeros), got {:?}",
            s
        ));
    }
    s.parse::<BigUint>()
        .map_err(|e| format!("parent_rev {:?}: {}", s, e))
}

/// Parse envelope bytes strictly (§8.6.1).
///
/// Unknown keys, missing keys, duplicated keys, reordered keys, a missing
/// trailing LF and trailing bytes are ALL errors — every one of them is a
/// distinct byte string that a lenient parser would map onto a statement the
/// author did not make. The parse finishes by re-encoding and comparing to the
/// input, which §8.6.1 requires explicitly: "canonical encoding without
/// canonical parsing would protect identity at creation and discard it at
/// verification".
pub fn parse(bytes: &[u8]) -> Result<Envelope, String> {
    // The envelope is text. §8.6.1 states its rules over CHARACTERS, so the
    // bytes must decode; a byte string that is not UTF-8 has no character
    // reading to check. (§11.2 says "UTF-8 throughout" for the campaign
    // encoding; §8.6.1 does not say it — see DIVERGENCES.md.)
    let text = std::str::from_utf8(bytes).map_err(|e| format!("envelope is not UTF-8: {}", e))?;

    // Line framing. Exactly seven LF-terminated lines and nothing after the
    // last LF: `split('\n')` on such a string yields eight pieces whose last is
    // empty. Anything else is a missing terminator or trailing content.
    let pieces: Vec<&str> = text.split('\n').collect();
    match pieces.last() {
        Some(&"") => {}
        _ => {
            return Err("missing trailing LF: every line, including the last, is LF-terminated"
                .to_string())
        }
    }
    let lines = &pieces[..pieces.len() - 1];
    if lines.len() != 1 + KEYS.len() {
        return Err(format!(
            "expected a version line and exactly {} field lines, got {} line(s)",
            KEYS.len(),
            lines.len()
        ));
    }
    if lines[0] != ENVELOPE_VERSION {
        return Err(format!(
            "version line must be {:?}, got {:?}",
            ENVELOPE_VERSION, lines[0]
        ));
    }

    // Fields, POSITIONALLY: the key at position i must be KEYS[i]. This is what
    // makes unknown / missing / duplicated / reordered keys all one check —
    // there is no key lookup to be lenient in.
    let mut values: Vec<&str> = Vec::with_capacity(KEYS.len());
    for (i, line) in lines[1..].iter().enumerate() {
        let (key, value) = match line.split_once('=') {
            Some(kv) => kv,
            None => return Err(format!("line {}: expected key=value, got {:?}", i + 2, line)),
        };
        if key != KEYS[i] {
            return Err(format!(
                "line {}: expected key {:?} in the fixed §8.6.1 order, got {:?}",
                i + 2,
                KEYS[i],
                key
            ));
        }
        values.push(value);
    }

    let parent_text = values[3];
    let parent = if parent_text == PARENT_NONE {
        None
    } else {
        Some(parent_text.to_string())
    };
    let env = Envelope {
        op: values[0].to_string(),
        name: values[1].to_string(),
        artifact: values[2].to_string(),
        parent,
        parent_rev: parse_canonical_decimal(values[4])?,
        author: values[5].to_string(),
    };
    env.validate()?;

    // The re-encode obligation. Redundant with the checks above today — which is
    // the point: it is a total statement about the parser, so any future
    // leniency that maps two byte strings onto one Envelope is caught here
    // instead of at signature-verification time in someone else's kernel.
    let reencoded = env.encode_raw();
    if reencoded != bytes {
        return Err(format!(
            "re-encoding the parsed envelope does not reproduce the input ({} bytes in, {} out)",
            bytes.len(),
            reencoded.len()
        ));
    }
    Ok(env)
}

// ---------------------------------------------------------------------------
// §8.6.2 — the name revision
// ---------------------------------------------------------------------------

/// A journal entry, reduced to the fields §8 and §8.6.3 name that this module
/// needs. Whatever reads a `log.jsonl` builds these; oathrs has no store, so
/// nothing here touches a filesystem.
///
/// Absent string fields are the empty string (the §8/§8.6.4 convention: "for
/// every entry where any of `envelope`, `author_pubkey`, `author_sig` is
/// non-empty"); `transition` is an `Option` because §8.6.2 and §8.6.3 give
/// ABSENCE a meaning distinct from any value it could hold.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Entry {
    /// `name` — the name this entry is about.
    pub name: String,
    /// `kind` — `put`, `prove`, `cross`, …
    pub kind: String,
    /// `status` — `accepted` | `falsified` | `rejected` | `blocked` | `pending`.
    pub status: String,
    /// `hash` — the stored object hash, empty on a gate rejection.
    pub hash: String,
    /// `prev` — the previous hash for the name on a repoint, else empty.
    pub prev: String,
    /// `transition` — `Some("applied")` when the name now points at `hash`.
    pub transition: Option<String>,
    /// `envelope` — the EXACT bytes as received, never re-encoded (§8.6.3).
    pub envelope: Vec<u8>,
    /// `author_pubkey` — lowercase hex of the key that signed `envelope`.
    pub author_pubkey: String,
    /// `author_sig` — lowercase hex of the 64-byte signature over `envelope`.
    pub author_sig: String,
}

impl Entry {
    /// Did this entry APPLY A TRANSITION to its name (§8.6.2)?
    ///
    /// `legacy` selects the fallback for entries written before the
    /// `transition` field existed: `accepted` and `falsified` count as applied,
    /// everything else does not. A falsified definition DOES bind its name, so
    /// counting only `accepted` undercounts — and an undercount silently
    /// reopens the A→B→A replay hole the revision exists to close.
    pub fn applied_transition(&self, legacy: bool) -> bool {
        match &self.transition {
            Some(t) => t == TRANSITION_APPLIED,
            None if legacy => self.status == "accepted" || self.status == "falsified",
            None => false,
        }
    }
}

/// Where the pre-`transition` era ends: the index of the first entry carrying a
/// `transition` field, or the journal length when none does.
///
/// §8.6.2 mandates a fallback "for entries written before that field existed"
/// but gives no way to RECOGNIZE such an entry — absence of `transition` means
/// "legacy, consult the status" under §8.6.2 and "did not apply" under §8.6.3.
/// The rule used here: the journal is append-only, so the era boundary is a
/// single point, and the first entry that carries the field marks it. Before
/// that point, absence means legacy; from it on, `transition` is authoritative.
/// This is a judgement call — see DIVERGENCES.md.
pub fn legacy_prefix_len(journal: &[Entry]) -> usize {
    journal
        .iter()
        .position(|e| e.transition.is_some())
        .unwrap_or(journal.len())
}

/// The current revision of `name` (§8.6.2): the number of journal entries that
/// have applied a transition to it.
///
/// A first publication is `parent=-`, `parent_rev=0`, which this returns for a
/// name that was never published — §8.6.2: "an unresolvable name is one that
/// was never published".
pub fn name_revision(journal: &[Entry], name: &str) -> u64 {
    let boundary = legacy_prefix_len(journal);
    journal
        .iter()
        .enumerate()
        .filter(|(i, e)| e.name == name && e.applied_transition(*i < boundary))
        .count() as u64
}

/// The hash `name` currently points at, or `None` when it was never published.
///
/// Derived from the same applied-transition rule as [`name_revision`], so the
/// pair a publication must match (`parent`, `parent_rev`) always comes from one
/// reading of the journal.
pub fn name_head(journal: &[Entry], name: &str) -> Option<String> {
    let boundary = legacy_prefix_len(journal);
    journal
        .iter()
        .enumerate()
        .filter(|(i, e)| e.name == name && e.applied_transition(*i < boundary))
        .map(|(_, e)| e.hash.clone())
        .next_back()
}

// ---------------------------------------------------------------------------
// §8.6.4 — verification obligations
// ---------------------------------------------------------------------------

/// The five MUST conditions of §8.6.4, for one entry.
///
/// An entry with none of `envelope`, `author_pubkey`, `author_sig` imposes no
/// obligation and returns `Ok`. An entry with SOME of them is a forged
/// attribution, not an unattributed entry, and is rejected.
pub fn verify_entry_publication(entry: &Entry) -> Result<(), String> {
    let has_env = !entry.envelope.is_empty();
    let has_key = !entry.author_pubkey.is_empty();
    let has_sig = !entry.author_sig.is_empty();
    if !has_env && !has_key && !has_sig {
        return Ok(());
    }
    // (1) all three present. Any one alone attests to nothing.
    if !(has_env && has_key && has_sig) {
        return Err(format!(
            "publication fields are partial (envelope: {}, author_pubkey: {}, author_sig: {}) — any one alone attests to nothing",
            has_env, has_key, has_sig
        ));
    }
    // (2) the envelope parses under §8.6.1 and re-encodes to itself. `parse`
    // does both.
    let env = parse(&entry.envelope).map_err(|e| format!("envelope: {}", e))?;
    // (3) the envelope's author equals author_pubkey. Compared as the byte
    // strings they are: both are required to be lowercase hex, so there is no
    // case folding to do and doing any would admit two spellings of one key.
    if env.author != entry.author_pubkey {
        return Err(format!(
            "envelope author {:?} is not the entry's author_pubkey {:?}",
            env.author, entry.author_pubkey
        ));
    }
    // (4) author_sig is valid under author_pubkey over the PERSISTED bytes —
    // not over a re-encoding. `entry.envelope` is what was stored; nothing on
    // this path re-derives it.
    let key = ed25519::from_hex_exact(&entry.author_pubkey, 32)
        .ok_or_else(|| format!("author_pubkey {:?} is not 64 lowercase hex", entry.author_pubkey))?;
    let sig = ed25519::from_hex_exact(&entry.author_sig, 64)
        .ok_or_else(|| format!("author_sig {:?} is not 128 lowercase hex", entry.author_sig))?;
    if !ed25519::verify(&key, &entry.envelope, &sig) {
        return Err("author_sig is not a valid Ed25519 signature under author_pubkey over the persisted envelope bytes".to_string());
    }
    // (5) the envelope's name, artifact and parent equal the entry's name, hash
    // and prev — an empty prev corresponding to `-`. Failing this means the
    // store recorded a transition its author did not sign, which is a hard
    // failure, never a warning.
    if env.name != entry.name {
        return Err(format!(
            "envelope name {:?} does not match the entry's name {:?}",
            env.name, entry.name
        ));
    }
    if env.artifact != entry.hash {
        return Err(format!(
            "envelope artifact {:?} does not match the entry's hash {:?}",
            env.artifact, entry.hash
        ));
    }
    let entry_parent: Option<&str> = if entry.prev.is_empty() {
        None
    } else {
        Some(entry.prev.as_str())
    };
    if env.parent.as_deref() != entry_parent {
        return Err(format!(
            "envelope parent {:?} does not match the entry's prev {:?}",
            env.parent_field(),
            entry.prev
        ));
    }
    Ok(())
}

/// [`verify_entry_publication`] over a whole journal, reporting the offending
/// position. A journal is rejected as a whole (§8, §8.6.4), so the first
/// failure ends it.
pub fn verify_journal_publications(journal: &[Entry]) -> Result<(), String> {
    for (i, entry) in journal.iter().enumerate() {
        verify_entry_publication(entry)
            .map_err(|e| format!("journal entry {} (name {:?}): {}", i, entry.name, e))?;
    }
    Ok(())
}

/// A name's current state, as a store knows it when a publication arrives.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NameState {
    /// The hash the name points at, or `None` when it was never published.
    pub head: Option<String>,
    /// The name's revision (§8.6.2).
    pub rev: u64,
}

impl NameState {
    /// A name that was never published: `parent=-`, `parent_rev=0`.
    pub fn unpublished() -> NameState {
        NameState { head: None, rev: 0 }
    }

    /// Read a name's state out of a journal, by the §8.6.2 rule.
    pub fn from_journal(journal: &[Entry], name: &str) -> NameState {
        NameState {
            head: name_head(journal, name),
            rev: name_revision(journal, name),
        }
    }
}

/// The store-side preconditions of §8.6.4, ALL of which must hold **before the
/// name moves**.
///
/// * `envelope_bytes` — what the client sent, verbatim.
/// * `author_sig_hex` — the client's signature over those exact bytes.
/// * `principal` — lowercase hex of the AUTHENTICATED principal's key. The
///   signature is checked against THIS, never against the key the envelope
///   names: verifying against the envelope's own `author` would always succeed,
///   so a caller could submit any valid statement made by anyone.
/// * `recomputed_artifact` — the hash the STORE computed from the submitted
///   content. Identity is a pure function of content (§1), so requiring it to
///   equal the signed `artifact` makes agreement between the client's and the
///   store's elaboration an enforced precondition rather than an assumption.
/// * `current` — the name's current `(head, rev)`.
///
/// On success the parsed envelope is returned, so a caller journals the fields
/// it interpreted from the same value it verified. On failure the name MUST NOT
/// move; the object MAY still be stored (storage is idempotent under content
/// addressing and an unreferenced object is inert), and the attempt SHOULD be
/// journaled.
pub fn accept_publication(
    envelope_bytes: &[u8],
    author_sig_hex: &str,
    principal: &str,
    recomputed_artifact: &str,
    current: &NameState,
) -> Result<Envelope, String> {
    let env = parse(envelope_bytes)?;

    // The signing key is the authenticated principal.
    let key = ed25519::from_hex_exact(principal, 32)
        .ok_or_else(|| format!("principal {:?} is not 64 lowercase hex", principal))?;
    let sig = ed25519::from_hex_exact(author_sig_hex, 64)
        .ok_or_else(|| format!("signature {:?} is not 128 lowercase hex", author_sig_hex))?;
    if !ed25519::verify(&key, envelope_bytes, &sig) {
        return Err(
            "signature does not verify under the authenticated principal over the submitted envelope bytes"
                .to_string(),
        );
    }
    // ...and the statement is the principal's own. §8.6.4(3) requires the
    // journaled `author_pubkey` to equal the envelope's `author`, and (4)
    // requires the signature to verify under it; with the principal check above,
    // all three must be one key. A statement by someone else, however valid, is
    // not this principal's publication.
    if env.author != principal {
        return Err(format!(
            "envelope author {:?} is not the authenticated principal {:?}",
            env.author, principal
        ));
    }
    // The store's own elaboration of the submitted content must agree.
    if env.artifact != recomputed_artifact {
        return Err(format!(
            "signed artifact {:?} is not the hash of the submitted content ({:?})",
            env.artifact, recomputed_artifact
        ));
    }
    // The signed parent and revision must be the name's CURRENT values. This is
    // the compare of a compare-and-swap; §8.6.5 is explicit that it does not by
    // itself make the swap atomic.
    if env.parent.as_deref() != current.head.as_deref() {
        return Err(format!(
            "signed parent {:?} is not the name's current value {:?}",
            env.parent_field(),
            current.head.as_deref().unwrap_or(PARENT_NONE)
        ));
    }
    if env.parent_rev != BigUint::from(current.rev) {
        return Err(format!(
            "signed parent_rev {} is not the name's current revision {}",
            env.parent_rev.to_str_radix(10),
            current.rev
        ));
    }
    Ok(env)
}

