                        "envtest canonical {}: RE-ENCODING DIFFERS ({} bytes in, {} out)",
                        n,
                        bytes.len(),
                        back.len()
                    );
                    *ok = false;
                }
                Err(e) => {
                    eprintln!("envtest canonical {}: re-encode rejected: {}", n, e);
                    *ok = false;
                }
            },
            Err(e) => {
                eprintln!("envtest canonical {}: WRONGLY REJECTED: {}", n, e);
                *ok = false;
            }
        }
    }

    for line in text.lines() {
        if line.starts_with('#') {
            continue;
        }
        if line.trim().is_empty() {
            flush(&mut block, &mut canonical, &mut ok);
            continue;
        }
        if let Some(rest) = line.strip_prefix("reject") {
            flush(&mut block, &mut canonical, &mut ok);
            rejects += 1;
            // `reject <label> "<Go-quoted bytes>"`: the label is free text, so
            // the vector starts at the first quote.
            let (label, quoted) = match rest.find('"') {
                Some(q) => (rest[..q].trim(), &rest[q..]),
                None => {
                    eprintln!("envtest reject {}: no quoted vector on the line", rejects);
                    ok = false;
                    continue;
                }
            };
            let bytes = match go_unquote(quoted.trim_end()) {
                Ok(b) => b,
                Err(e) => {
                    eprintln!("envtest reject {:?}: cannot unquote vector: {}", label, e);
                    ok = false;
                    continue;
                }
            };
            match publish::parse(&bytes) {
                Err(_) => println!("envtest reject {}: ok ({})", rejects, label),
                Ok(_) => {
                    eprintln!("envtest reject {}: WRONGLY ACCEPTED ({})", rejects, label);
                    ok = false;
                }
            }
            continue;
        }
        block.push(line);
    }
    flush(&mut block, &mut canonical, &mut ok);

    if canonical == 0 || rejects == 0 {
        eprintln!(
            "envtest: fixture yielded {} canonical block(s) and {} reject case(s) — the file was not understood",
            canonical, rejects
        );
        return 1;
    }
    println!(
        "envtest: {} canonical envelope(s) byte-identical, {} reject case(s) rejected",
        canonical, rejects
    );
    if ok {
        0
    } else {
        1
    }
}

/// Unquote a Go `%q` double-quoted string to BYTES.
///
/// The reject vectors in `fixtures/envelope/vectors.txt` are written this way
/// because the file is line-oriented and the vectors contain LFs. Byte-level
/// escapes (`\xNN`) can denote invalid UTF-8, so the result is a byte vector,
/// not a `String` — a kernel must be able to reject a vector that is not text
/// at all.
fn go_unquote(s: &str) -> Result<Vec<u8>, String> {
    let b = s.as_bytes();
    if b.len() < 2 || b[0] != b'"' || b[b.len() - 1] != b'"' {
        return Err(format!("not a double-quoted string: {:?}", s));
    }
    let inner = &b[1..b.len() - 1];
    let mut out: Vec<u8> = Vec::with_capacity(inner.len());
    let mut i = 0usize;
    let hexval = |c: u8| -> Result<u32, String> {
        match c {
            b'0'..=b'9' => Ok((c - b'0') as u32),
            b'a'..=b'f' => Ok((c - b'a' + 10) as u32),
            b'A'..=b'F' => Ok((c - b'A' + 10) as u32),
            _ => Err(format!("bad hex digit {:?}", c as char)),
        }
    };
    let take_hex = |inner: &[u8], i: &mut usize, n: usize| -> Result<u32, String> {
        let mut v = 0u32;
        for _ in 0..n {
            if *i >= inner.len() {
                return Err("truncated hex escape".to_string());
            }
            v = v * 16 + hexval(inner[*i])?;
            *i += 1;
        }
        Ok(v)
    };
    while i < inner.len() {
        let c = inner[i];
        if c != b'\\' {
            out.push(c);
            i += 1;
            continue;
        }
        i += 1;
        if i >= inner.len() {
            return Err("trailing backslash".to_string());
        }
        let e = inner[i];
        i += 1;
        match e {
            b'a' => out.push(0x07),
            b'b' => out.push(0x08),
            b'f' => out.push(0x0c),
            b'n' => out.push(b'\n'),
            b'r' => out.push(b'\r'),
            b't' => out.push(b'\t'),
            b'v' => out.push(0x0b),
            b'\\' => out.push(b'\\'),
            b'\'' => out.push(b'\''),
            b'"' => out.push(b'"'),
            // \xNN is a BYTE, not a code point — this is how %q renders a byte
            // that is not valid UTF-8.
            b'x' => out.push(take_hex(inner, &mut i, 2)? as u8),
            b'u' | b'U' => {
                let n = if e == b'u' { 4 } else { 8 };
                let cp = take_hex(inner, &mut i, n)?;
                let ch = char::from_u32(cp)
                    .ok_or_else(|| format!("\\{} escape is not a code point: {:x}", e as char, cp))?;
                let mut buf = [0u8; 4];
                out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
            }
            b'0'..=b'7' => {
                // Three octal digits, the first already consumed.
                let mut v = (e - b'0') as u32;
                for _ in 0..2 {
                    if i >= inner.len() || !(b'0'..=b'7').contains(&inner[i]) {
                        return Err("truncated octal escape".to_string());
                    }
                    v = v * 8 + (inner[i] - b'0') as u32;
                    i += 1;
                }
                if v > 0xff {
                    return Err(format!("octal escape out of byte range: {}", v));
                }
                out.push(v as u8);
            }
            other => return Err(format!("unknown escape \\{}", other as char)),
        }
    }
    Ok(out)
}

