#!/usr/bin/env python3
# RFC 8032 Appendix A style reference implementation, written independently of
# the Rust, purely as an oracle for the test vectors.
import hashlib

p = 2**255 - 19
L = 2**252 + 27742317777372353535851937790883648493
d = (-121665 * pow(121666, p-2, p)) % p
I = pow(2, (p-1)//4, p)


def xrecover(y, sign):
    xx = (y*y-1) * pow(d*y*y+1, p-2, p) % p
    x = pow(xx, (p+3)//8, p)
    if (x*x - xx) % p != 0:
        x = (x*I) % p
    if (x*x - xx) % p != 0:
        return None
    if x % 2 != sign:
        x = p - x
    return x


By = 4 * pow(5, p-2, p) % p
Bx = xrecover(By, 0)
B = (Bx % p, By % p, 1, (Bx*By) % p)


def add(P, Q):
    A = (P[1]-P[0])*(Q[1]-Q[0]) % p
    Bb = (P[1]+P[0])*(Q[1]+Q[0]) % p
    C = 2*P[3]*Q[3]*d % p
    D = 2*P[2]*Q[2] % p
    E, F, G, H = Bb-A, D-C, D+C, Bb+A
    return (E*F % p, G*H % p, F*G % p, E*H % p)


def mul(k, P):
    Q = (0, 1, 1, 0)
    for i in reversed(range(k.bit_length())):
        Q = add(Q, Q)
        if (k >> i) & 1:
            Q = add(Q, P)
    return Q


def encode(P):
    zi = pow(P[2], p-2, p)
    x = P[0]*zi % p
    y = P[1]*zi % p
    return int.to_bytes(y | ((x & 1) << 255), 32, 'little')


def H(m):
    return hashlib.sha512(m).digest()


def secret_expand(seed):
    h = H(seed)
    a = int.from_bytes(h[:32], 'little')
    a &= (1 << 254) - 8
    a |= (1 << 254)
    return a, h[32:]


def pk(seed):
    a, _ = secret_expand(seed)
    return encode(mul(a, B))


def sign(seed, msg):
    a, prefix = secret_expand(seed)
    A = encode(mul(a, B))
    r = int.from_bytes(H(prefix + msg), 'little') % L
    R = encode(mul(r, B))
    k = int.from_bytes(H(R + A + msg), 'little') % L
    S = (r + k*a) % L
    return R + int.to_bytes(S, 32, 'little')


VECTORS = [
    ("9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60", ""),
    ("4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb", "72"),
    ("c5aa8df43f9f837bedb7442f31dcb7b166d38535076f094b85ce3a2e0b4458f7", "af82"),
]

for seed, msg in VECTORS:
    s = bytes.fromhex(seed)
    m = bytes.fromhex(msg)
    print("pk =", pk(s).hex())
    print("sig=", sign(s, m).hex())

